script:
frappe.ui.form.on('Floors And Rooms Master', {

    refresh(frm) {

        // ==========================================
        // ปุ่ม Generate QR Code จาก Field ใน DocType
        // ==========================================
        if (frm.fields_dict.generate_qr && frm.fields_dict.generate_qr.$input) {
            frm.fields_dict.generate_qr.$input.off('click').on('click', async function () {

                // ตรวจสอบชั้น
                if (!frm.doc.floor) {
                    frappe.msgprint('กรุณาระบุชั้นก่อนค่ะ');
                    return;
                }

                // ตรวจสอบห้อง
                if (!frm.doc.rooms) {
                    frappe.msgprint('กรุณาระบุห้องก่อนค่ะ');
                    return;
                }

                // URL หน้า Housekeeping Services
                // URL หน้า Housekeeping Services (ใช้โดเมน Production ถาวร)
                const baseUrl = 'https://sehsmart.surateyehospital.com/Housekeeping%20Services/room_cleaning';

                // สร้าง URL CHECK-IN
                const checkin_url = baseUrl +
                    '?type=ROOM_CLEANING_CHECK_IN' +
                    '&floor=' + encodeURIComponent(frm.doc.floor) +
                    '&rooms=' + encodeURIComponent(frm.doc.rooms);

                // สร้าง URL CHECK-OUT
                const checkout_url = baseUrl +
                    '?type=ROOM_CLEANING_CHECK_OUT' +
                    '&floor=' + encodeURIComponent(frm.doc.floor) +
                    '&rooms=' + encodeURIComponent(frm.doc.rooms);

                // สร้าง QR CHECK-IN
                const checkin_qr = 'https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=' +
                    encodeURIComponent(checkin_url);

                // สร้าง QR CHECK-OUT
                const checkout_qr = 'https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=' +
                    encodeURIComponent(checkout_url);

                // บันทึก URL ลง Long Text
                frm.set_value('qr_checkin_data', checkin_url);
                frm.set_value('qr_checkout_data', checkout_url);

                // แสดง QR Code
                frm.fields_dict.qr_code_display.$wrapper.html(`
                    <div style="
                        display:flex;
                        gap:40px;
                        justify-content:center;
                        align-items:flex-start;
                        padding:25px;
                        flex-wrap:wrap;
                    ">
                        <div style="
                            text-align:center;
                            border:1px solid #ddd;
                            border-radius:12px;
                            padding:20px;
                            width:320px;
                            background:#fff;
                        ">
                            <div style="
                                font-size:18px;
                                font-weight:600;
                                margin-bottom:15px;
                                color:#16a34a;
                            ">
                                QR CHECK-IN
                            </div>

                            <img
                                src="${checkin_qr}"
                                alt="QR CHECK-IN"
                                style="
                                    width:250px;
                                    height:250px;
                                    object-fit:contain;
                                "
                            >

                            <div style="
                                margin-top:15px;
                                font-size:14px;
                                color:#666;
                            ">
                                ${frappe.utils.escape_html(String(frm.doc.floor))}
                                -
                                ${frappe.utils.escape_html(String(frm.doc.rooms))}
                            </div>
                        </div>

                        <div style="
                            text-align:center;
                            border:1px solid #ddd;
                            border-radius:12px;
                            padding:20px;
                            width:320px;
                            background:#fff;
                        ">
                            <div style="
                                font-size:18px;
                                font-weight:600;
                                margin-bottom:15px;
                                color:#dc2626;
                            ">
                                QR CHECK-OUT
                            </div>

                            <img
                                src="${checkout_qr}"
                                alt="QR CHECK-OUT"
                                style="
                                    width:250px;
                                    height:250px;
                                    object-fit:contain;
                                "
                            >

                            <div style="
                                margin-top:15px;
                                font-size:14px;
                                color:#666;
                            ">
                                ${frappe.utils.escape_html(String(frm.doc.floor))}
                                -
                                ${frappe.utils.escape_html(String(frm.doc.rooms))}
                            </div>
                        </div>
                    </div>
                `);

                // SAVE ทันทีหลัง Generate
                await frm.save();
            });
        }

        // ==========================================
        // แสดง QR ที่บันทึกไว้
        // ==========================================
        if (frm.doc.qr_checkin_data && frm.doc.qr_checkout_data) {

            const checkin_qr = 'https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=' +
                encodeURIComponent(frm.doc.qr_checkin_data);

            const checkout_qr = 'https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=' +
                encodeURIComponent(frm.doc.qr_checkout_data);

            frm.fields_dict.qr_code_display.$wrapper.html(`
                <div style="
                    display:flex;
                    gap:40px;
                    justify-content:center;
                    align-items:flex-start;
                    padding:25px;
                    flex-wrap:wrap;
                ">
                    <div style="
                        text-align:center;
                        border:1px solid #ddd;
                        border-radius:12px;
                        padding:20px;
                        width:320px;
                        background:#fff;
                    ">
                        <div style="
                            font-size:18px;
                            font-weight:600;
                            margin-bottom:15px;
                            color:#16a34a;
                        ">
                            QR CHECK-IN
                        </div>

                        <img
                            src="${checkin_qr}"
                            alt="QR CHECK-IN"
                            style="
                                width:250px;
                                height:250px;
                                object-fit:contain;
                            "
                        >

                        <div style="
                            margin-top:15px;
                            font-size:14px;
                            color:#666;
                        ">
                            ${frappe.utils.escape_html(String(frm.doc.floor || ''))}
                            -
                            ${frappe.utils.escape_html(String(frm.doc.rooms || ''))}
                        </div>
                    </div>

                    <div style="
                        text-align:center;
                        border:1px solid #ddd;
                        border-radius:12px;
                        padding:20px;
                        width:320px;
                        background:#fff;
                    ">
                        <div style="
                            font-size:18px;
                            font-weight:600;
                            margin-bottom:15px;
                            color:#dc2626;
                        ">
                            QR CHECK-OUT
                        </div>

                        <img
                            src="${checkout_qr}"
                            alt="QR CHECK-OUT"
                            style="
                                width:250px;
                                height:250px;
                                object-fit:contain;
                            "
                        >

                        <div style="
                            margin-top:15px;
                            font-size:14px;
                            color:#666;
                        ">
                            ${frappe.utils.escape_html(String(frm.doc.floor || ''))}
                            -
                            ${frappe.utils.escape_html(String(frm.doc.rooms || ''))}
                        </div>
                    </div>
                </div>
            `);
        }

    }

});

frappe.ui.form.on('Cleaning Checklist For Rooms', {
    setup(frm) {
        frm.set_query('cleaner_name', function() {
            return { filters: { department: 'งานทำความสะอาด' } };
        });
    },

    onload(frm) {
        validate_scan_type(frm);
    },

    refresh(frm) {
        toggle_checklist_sections(frm);
        validate_scan_type(frm);
    },

    floor(frm) {
        toggle_checklist_sections(frm);
    },

    checkout_time(frm) {
        if (!has_valid_checkin(frm)) {
            frm.set_value('checkout_time', '');
            frm.refresh_field('checkout_time');
            show_checkout_alert();
        }
    },

    before_save(frm) {
        if (!has_valid_checkin(frm)) {
            frappe.validated = false;
            show_checkout_alert();
            return false;
        }
    }
});

// 🔴 ฟังก์ชันดักจับการสแกน QR CHECK-OUT ในครั้งแรก
function validate_scan_type(frm) {
    let urlParams = new URLSearchParams(window.location.search);
    let is_checkout_scan = urlParams.get('scan_type') === 'checkout';

    // ถ้าเป็นการเผลอสแกน QR CHECK-OUT เข้ามาแต่ยังไม่ได้ Check-in ในระบบ
    if (is_checkout_scan && !has_valid_checkin(frm)) {
        
        // 1. ล็อกฟอร์มและซ่อนส่วนลงข้อมูล
        frm.disable_form();
        if (frm.wrapper) {
            $(frm.wrapper).find('.form-page').hide();
        }

        // 2. เด้ง Popup แจ้งเตือนห้ามทำรายการ
        show_checkout_alert();
    }
}

function has_valid_checkin(frm) {
    let checkin = frm.doc.checkin_time;
    if (!checkin) return false;
    let str = checkin.toString().trim();
    return str !== "" && str !== "00:00:00" && str !== "null" && str !== "undefined";
}

function show_checkout_alert() {
    frappe.msgprint({
        title: __('แจ้งเตือนการสแกน'),
        indicator: 'red',
        message: __('<b>ห้ามสแกน QR Code Check-out ก่อน!</b><br>กรุณาสแกน QR Code Check-in เพื่อเข้าทำความสะอาดก่อน'),
        primary_action: {
            label: __('ตกลง'),
            action: function() {
                if (window.history.length > 1) {
                    window.history.back();
                }
            }
        }
    });
}

function toggle_checklist_sections(frm) {
    let floor_val = (frm.doc.floors || "").toString().trim();

    if (!floor_val) {
        frm.set_df_property('section_break_jcqo', 'hidden', 1);
        frm.set_df_property('section_break_uamq', 'hidden', 1);
        return;
    }

    let is_floor_1_3 = floor_val.includes('1') || floor_val.includes('2') || floor_val.includes('3');
    let is_floor_4_6 = floor_val.includes('4') || floor_val.includes('6');

    if (is_floor_1_3) {
        frm.set_df_property('section_break_jcqo', 'hidden', 0);
        frm.set_df_property('section_break_uamq', 'hidden', 1);
    } else if (is_floor_4_6) {
        frm.set_df_property('section_break_jcqo', 'hidden', 1);
        frm.set_df_property('section_break_uamq', 'hidden', 0);
    } else {
        frm.set_df_property('section_break_jcqo', 'hidden', 1);
        frm.set_df_property('section_break_uamq', 'hidden', 1);
    }

    frm.refresh_fields();
}
